import data from "../demo/portaldot-local.json";
import "./localnode.css";

// Everything below comes from src/demo/portaldot-local.json, generated by
// scripts/import-local-node.mjs from evidence/portaldot-local-node/. No value is typed in by hand.
const D = data;
const short = (s: string, n = 10) => (s.length > n * 2 ? `${s.slice(0, n)}…${s.slice(-6)}` : s);
const PASS: Record<string, string> = {
  step_order: "step is next in order", approval_unused: "approval not yet used for this step", approval_valid_time: "approval not expired",
  approval_intact: "approval not altered", approval_matches: "sending exactly what was approved", runtime_unchanged: "runtime unchanged",
  signed_bytes_match: "signed bytes match approved calls", signed_dry_run_ok: "signed dry run ok",
};

export const LOCAL_NODE_BANNER = "Local Portaldot dev node, spec 1002, not the public testnet";

export function LocalNodeBanner() {
  return <div className="ln-banner" role="note">{LOCAL_NODE_BANNER}<small>Throwaway local chain, public //Alice dev signer. Not the V3 testnet, not mainnet.</small></div>;
}

function Gate({ rows }: { rows: typeof D.sequential.gate }) {
  return (
    <table><thead><tr><th>Step</th><th>Gate phase</th><th>Result</th><th>Checks passed</th></tr></thead><tbody>
      {rows.map((g, i) => (
        <tr key={i}><td><b>{g.actionId}</b></td><td>{g.phase}</td>
          <td className={g.ok ? "ok" : "bad"}>{g.ok ? "all passed" : g.reasons.join(", ")}</td>
          <td className="muted">{g.passed.map((c) => PASS[c] ?? c).join("; ")}</td></tr>
      ))}
    </tbody></table>
  );
}
const Steps = ({ steps }: { steps: typeof D.sequential.steps }) => (
  <table><thead><tr><th>Step</th><th>Status</th><th>Block</th><th>Tx</th></tr></thead><tbody>
    {steps.map((s) => <tr key={s.id}><td><b>{s.id}</b></td><td>{s.status}</td><td>#{s.block}</td><td><code title={s.tx}>{short(s.tx)}</code></td></tr>)}
  </tbody></table>
);

export function LocalNodeEvidence() {
  const n = D.node, rb = D.rollback;
  return (
    <div className="ln" id="local-node-evidence">
      <LocalNodeBanner />
      <div className="ln-card">
        <h3>Node and runtime</h3>
        <p className="muted">Recorded {new Date(D.startedAt).toUTCString()} from the organizers' node binary on this machine (<code>--dev --tmp</code>, localhost only). The console replays the recording and is not connected live.</p>
        <ul>
          <li>Endpoint <code>{n.endpoint}</code>; spec <b>{n.specName} {n.specVersion}</b>, tx version {n.transactionVersion}, metadata V{n.metadataVersion}, {n.palletCount} pallets.</li>
          <li>Genesis <code>{n.genesisHash}</code> (a throwaway dev genesis, not mainnet's).</li>
          <li>Runtime fingerprint digest <code>{n.fingerprintDigest}</code>, {n.fingerprintStableOnRefetch ? "stable on refetch" : "not stable on refetch"}.</li>
          <li>Contracts pallet: {n.hasContracts ? "yes (old, rent-based shape)" : "no"}; Revive: {n.hasRevive ? "yes" : "no"}; Assets: {n.hasAssets ? "yes" : "no"}; Utility: {n.hasUtility ? "yes" : "no"}.</li>
          <li>Token {n.token.symbol}, {n.token.decimals} decimals: declared on the command line, the node reports none.</li>
          <li>Signer <code>{D.signer}</code> (public //Alice dev account).</li>
        </ul>
      </div>
      <div className="ln-card">
        <h3>1. Contract deploy</h3>
        <p>Tx <code>{D.deploy.txHash}</code> in block #{D.deploy.block}, {D.deploy.status}, signed dry run {D.deploy.dryRun}. Contract <code>{D.deploy.contract}</code>, code hash <code>{short(D.deploy.codeHash)}</code>.</p>
        <p className="muted"><b>What was deployed:</b> a small hand-written Wasm emitter using the old <code>seal_*</code> API. The ink! 5 demo contract cannot run on this old pallet (it imports <code>seal0.input</code> and <code>seal2.set_storage</code>); its signed dry run fails and nothing is sent. So the contract step below is a raw-data call, not a call by message name.</p>
        <p className="muted">Source: <code>{D.deploy.file}</code></p>
      </div>
      <div className="ln-card">
        <h3>2. Sequential run: {D.sequential.result} (mode: {D.sequential.compiledMode})</h3>
        <Steps steps={D.sequential.steps} />
        <p className="muted">The <code>call</code> step is a raw-data <code>Contracts.call</code> to the Wasm emitter with data <code>{short(D.contractCall, 14)}</code>, shaped like <code>settle(7, 2500)</code>. The emitter's event carries "SEAM" plus that input.</p>
        <h4>Submit gate at every step</h4>
        <Gate rows={D.sequential.gate} />
        <p className="muted">Source: <code>{D.sequential.file}</code></p>
      </div>
      <div className="ln-card">
        <h3>3. Atomic run: {D.atomic.result} (mode: {D.atomic.compiledMode})</h3>
        <p>All three steps in one <code>Utility.batch_all</code>, tx <code>{D.atomic.steps[0].tx}</code>, block #{D.atomic.steps[0].block}.</p>
        <Gate rows={D.atomic.gate} />
        <p className="muted">Source: <code>{D.atomic.file}</code></p>
      </div>
      <div className="ln-card">
        <h3>4. Rollback: {rb.result}, fails with <code>assets.BalanceLow</code></h3>
        <p>A <code>batch_all</code> whose second step overdraws. The gate <b className="bad">blocked it</b> ({rb.gateReasons.map((r) => r.code).join(", ")}): {rb.dryRun} {rb.nothingSent ? "Nothing was sent." : ""}</p>
        <p>As a labelled test-only bypass the same signed bytes were then sent anyway: tx <code>{rb.directTx}</code> ({rb.bypassStatuses.join(" → ")}). It failed as a whole with <code>{rb.dispatchError}</code></p>
        <table><thead><tr><th></th><th>Before (#{rb.state.before.block})</th><th>After bypass (#{rb.state.after.block})</th></tr></thead><tbody>
          {Object.keys(rb.state.before.balances).map((k) => <tr key={k}><td>{k}</td><td>{(rb.state.before.balances as Record<string, string>)[k]}</td><td>{(rb.state.after.balances as Record<string, string>)[k]}</td></tr>)}
          <tr><td>supply</td><td>{rb.state.before.supply}</td><td>{rb.state.after.supply}</td></tr>
          <tr><td>signer nonce</td><td>{rb.state.before.signerNonce}</td><td>{rb.state.after.signerNonce}</td></tr>
        </tbody></table>
        <p className="muted">Asset balances and supply are unchanged; the nonce moved because the fee was charged. batch_all rollback: {rb.batchAllRollback}. Source: <code>{rb.file}</code></p>
      </div>
      <div className="ln-card">
        <h3>Not done yet</h3>
        <ul>
          <li><span className="pending">PENDING</span> Signing in a real browser wallet. Every run above used the public //Alice dev key.</li>
          <li><span className="pending">PENDING</span> Run on the hosted Portaldot V3 testnet (RPC and faucet not available yet).</li>
          <li><span className="pending">PENDING</span> Contract call by message name on this runtime (needs an ink! 3-era build of the demo contract).</li>
        </ul>
      </div>
    </div>
  );
}
